mapper.select:
SELECT annual_salary
FROM USERS
WHERE id = #{userId}

SELECT CASE WHEN t.category IN ('OTHER', 'ETC') THEN 'ETC' ELSE t.category END AS category, COALESCE(SUM( CASE WHEN t.transaction_date BETWEEN #{currentStartDate} AND #{currentEndDate} THEN t.amount ELSE 0 END ), 0) AS currentAmount, COALESCE(SUM( CASE WHEN t.transaction_date BETWEEN #{previousStartDate} AND #{previousEndDate} THEN t.amount ELSE 0 END ), 0) AS previousAmount FROM TRANSACTIONS t
WHERE t.user_id = #{userId} AND t.type = 'EXPENSE' AND t.category NOT IN ('INCOME', 'SEND', 'CARD_WITHDRAWAL', 'LOAN_REPAYMENT') AND t.transaction_date BETWEEN #{previousStartDate} AND #{currentEndDate}
GROUP BY CASE WHEN t.category IN ('OTHER', 'ETC') THEN 'ETC' ELSE t.category END ORDER BY category ASC
